namespace format_dari\external;

use core_external\external_api;

defined('MOODLE_INTERNAL') || die();

require_once(__DIR__ . '/external_testcase.php');

/**
 * Tests for Ask Dari's answer format contract.
 *
 * @package    format_dari
 * @category   test
 * @copyright  2026 Dari Learning
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 * @covers     \format_dari\external\ai_chat
 */
#[\PHPUnit\Framework\Attributes\CoversClass(\format_dari\external\ai_chat::class)]
final class ai_chat_format_test extends external_testcase {
    /**
     * The guidelines carry the Markdown and quiz-block contract, and the academic-integrity rule
     * for practice questions.
     */
    public function test_guidelines_carry_the_response_format(): void {
        $method = new \ReflectionMethod(ai_chat::class, 'get_pedagogical_guidelines');
        $guidelines = $method->invoke(null);

        $this->assertStringContainsString('RESPONSE FORMAT', $guidelines);
        $this->assertStringContainsString('"quiz"', $guidelines);
        $this->assertStringContainsString('"answer": "B"', $guidelines);
        $this->assertStringContainsString('the LETTER of the correct option', $guidelines);
        $this->assertStringContainsString('- [ ] Item', $guidelines);
        $this->assertStringContainsString('Never copy, reword or reveal a question', $guidelines);
        // The integrity and grounding rules are there.
        $this->assertStringContainsString('Never give the answer to a quiz, knowledge check or assessment question', $guidelines);
        $this->assertStringContainsString('The material contains no answer keys.', $guidelines);
        $this->assertStringNotContainsString('Rules 2 and 4 do not apply', $guidelines);

        // With answer keys shared, the tutor is told how to treat them; a teacher is exempt.
        $shared = $method->invoke(null, true, true);
        $this->assertStringContainsString('may contain answer keys and marking guides', $shared);
        $this->assertStringContainsString('Rules 2 and 4 do not apply', $shared);
    }

    /**
     * A Markdown answer with a quiz block comes back byte for byte: newlines, fences, angle
     * brackets and JSON intact. The browser renders it; the server must not touch it.
     */
    public function test_answer_is_returned_verbatim(): void {
        $this->setUser($this->student);
        $fence = str_repeat(chr(96), 3);
        $answer = "Let's practise.\n\n{$fence}quiz\n[{\"question\": \"Is 2 < 3?\", \"options\": [\"Yes\", \"No\"], "
            . "\"answer\": 0, \"explanation\": \"**Yes**.\"}]\n{$fence}\n\n> **Tip:** <b>not html</b>\n\n- [ ] Review";
        $this->queue_text_reply($answer);

        $result = ai_chat::execute($this->course->id, 'Give me a practice question');
        $result = external_api::clean_returnvalue(ai_chat::execute_returns(), $result);

        $this->assertSame($answer, $result['answer']);
        $this->assertGreaterThan(0, $result['chatid']);
    }

    /**
     * Reasoning that a local model returns inline is removed before the learner sees it.
     */
    public function test_inline_reasoning_is_removed(): void {
        $this->setUser($this->student);
        $this->queue_text_reply("<think>The user wants the answer. I must not.</think>\nWhat do you already know?");

        $result = ai_chat::execute($this->course->id, 'Answer please');
        $this->assertSame('What do you already know?', $result['answer']);
    }

    /**
     * A follow-up generated by a quiz card (quotes, a closing bracket, a full stop after a
     * letter) is accepted as a learner question.
     */
    public function test_quiz_follow_up_is_accepted(): void {
        global $DB;
        $this->setUser($this->student);
        $this->queue_text_reply('Yes, that is right.');
        $question = get_string('aiassistant_quiz_choose', 'format_dari', (object) [
            'question' => 'Which statement is a point in time?',
            'letter' => 'C',
            'option' => 'Balance sheet',
        ]);

        $result = ai_chat::execute($this->course->id, $question);
        $result = external_api::clean_returnvalue(ai_chat::execute_returns(), $result);

        $logged = $DB->get_record('format_dari_chats', ['id' => $result['chatid']], '*', MUST_EXIST);
        $this->assertSame($question, $logged->question);
        $this->assertStringContainsString('my answer is C) Balance sheet', $logged->question);
    }

    /**
     * The answer says whether it was cut off: from the provider's finish reason when it reports
     * one, otherwise from an answer that visibly stops part-way.
     */
    public function test_truncated_flag(): void {
        $this->setUser($this->student);
        $cases = [
            ['Here are three questions, designed to test', 'stop', true],
            ['A complete answer.', 'stop', false],
            ['A complete answer.', 'length', true],
            ['A complete answer.', 'max_tokens', true],
            ['A complete answer.', 'end_turn', false],
        ];
        foreach ($cases as $i => [$answer, $finish, $expected]) {
            $this->queue_text_reply($answer, $finish);
            $result = ai_chat::execute($this->course->id, 'Question number ' . $i);
            $result = external_api::clean_returnvalue(ai_chat::execute_returns(), $result);
            $this->assertSame($expected, $result['truncated'], "case $i");
        }
    }

    /**
     * The format rules ask for a direct answer that starts with the practice questions, so a
     * limited answer is spent on the questions rather than a greeting.
     */
    public function test_guidelines_ask_for_direct_answers(): void {
        $method = new \ReflectionMethod(ai_chat::class, 'get_pedagogical_guidelines');
        $guidelines = $method->invoke(null);

        $this->assertStringContainsString('Start with the substance: no greeting', $guidelines);
        $this->assertStringContainsString('Start your reply with the quiz block itself', $guidelines);
        $this->assertStringNotContainsString('one-line introduction before it', $guidelines);
    }
}
